CREATE TABLE public.scout_workspaces (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES public.tenants(id), account_id uuid NOT NULL, name text NOT NULL DEFAULT 'Demand Scout', state jsonb NOT NULL DEFAULT '{}'::jsonb, revision integer NOT NULL DEFAULT 0, is_demo boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,tenant_id), UNIQUE(account_id), FOREIGN KEY(account_id,tenant_id) REFERENCES public.accounts(id,tenant_id));
GRANT SELECT,INSERT,UPDATE ON public.scout_workspaces TO authenticated; GRANT ALL ON public.scout_workspaces TO service_role;
ALTER TABLE public.scout_workspaces ENABLE ROW LEVEL SECURITY;
CREATE POLICY scout_workspace_read ON public.scout_workspaces FOR SELECT TO authenticated USING(public.is_account_member(account_id));
CREATE POLICY scout_workspace_insert ON public.scout_workspaces FOR INSERT TO authenticated WITH CHECK(public.has_account_role(account_id,ARRAY['owner','admin','operator']::public.account_role[]));
CREATE POLICY scout_workspace_update ON public.scout_workspaces FOR UPDATE TO authenticated USING(public.has_account_role(account_id,ARRAY['owner','admin','operator']::public.account_role[])) WITH CHECK(public.has_account_role(account_id,ARRAY['owner','admin','operator']::public.account_role[]));
CREATE TABLE public.scout_sources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, workspace_id uuid NOT NULL, name text NOT NULL, provider text NOT NULL, mode text NOT NULL DEFAULT 'demo' CHECK(mode IN('demo','live')), status text NOT NULL DEFAULT 'not_connected' CHECK(status IN('not_connected','demo','connected')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,tenant_id), FOREIGN KEY(workspace_id,tenant_id) REFERENCES public.scout_workspaces(id,tenant_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.scout_sources TO authenticated; GRANT ALL ON public.scout_sources TO service_role;
ALTER TABLE public.scout_sources ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.scout_businesses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, workspace_id uuid NOT NULL, name text NOT NULL, industry text NOT NULL, geography text, is_demo boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,tenant_id), FOREIGN KEY(workspace_id,tenant_id) REFERENCES public.scout_workspaces(id,tenant_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.scout_businesses TO authenticated; GRANT ALL ON public.scout_businesses TO service_role;
ALTER TABLE public.scout_businesses ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.scout_contacts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, workspace_id uuid NOT NULL, business_id uuid, name text, public_url text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,tenant_id), FOREIGN KEY(workspace_id,tenant_id) REFERENCES public.scout_workspaces(id,tenant_id), FOREIGN KEY(business_id,tenant_id) REFERENCES public.scout_businesses(id,tenant_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.scout_contacts TO authenticated; GRANT ALL ON public.scout_contacts TO service_role;
ALTER TABLE public.scout_contacts ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.scout_signals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, workspace_id uuid NOT NULL, source_id uuid, business_id uuid, external_key text NOT NULL, original_text text NOT NULL, public_url text, pain text, intent text, published_at timestamptz, is_demo boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,tenant_id), UNIQUE(workspace_id,external_key), FOREIGN KEY(workspace_id,tenant_id) REFERENCES public.scout_workspaces(id,tenant_id), FOREIGN KEY(source_id,tenant_id) REFERENCES public.scout_sources(id,tenant_id), FOREIGN KEY(business_id,tenant_id) REFERENCES public.scout_businesses(id,tenant_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.scout_signals TO authenticated; GRANT ALL ON public.scout_signals TO service_role;
ALTER TABLE public.scout_signals ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.scout_solution_catalog (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, workspace_id uuid NOT NULL, name text NOT NULL, offer text NOT NULL, pain_tags text[] NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,tenant_id), FOREIGN KEY(workspace_id,tenant_id) REFERENCES public.scout_workspaces(id,tenant_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.scout_solution_catalog TO authenticated; GRANT ALL ON public.scout_solution_catalog TO service_role;
ALTER TABLE public.scout_solution_catalog ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.scout_playbooks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, workspace_id uuid NOT NULL, name text NOT NULL, industry text NOT NULL, weights jsonb NOT NULL DEFAULT '{}', threshold integer NOT NULL DEFAULT 75 CHECK(threshold BETWEEN 0 AND 100), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,tenant_id), FOREIGN KEY(workspace_id,tenant_id) REFERENCES public.scout_workspaces(id,tenant_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.scout_playbooks TO authenticated; GRANT ALL ON public.scout_playbooks TO service_role;
ALTER TABLE public.scout_playbooks ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.scout_opportunities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, workspace_id uuid NOT NULL, signal_id uuid, business_id uuid, solution_id uuid, external_key text NOT NULL, status text NOT NULL DEFAULT 'review' CHECK(status IN('review','approved','dismissed')), score integer NOT NULL DEFAULT 0 CHECK(score BETWEEN 0 AND 100), estimated_min numeric NOT NULL DEFAULT 0, estimated_max numeric NOT NULL DEFAULT 0, is_demo boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,tenant_id), UNIQUE(workspace_id,external_key), CHECK(estimated_min >= 0 AND estimated_max >= estimated_min), FOREIGN KEY(workspace_id,tenant_id) REFERENCES public.scout_workspaces(id,tenant_id), FOREIGN KEY(signal_id,tenant_id) REFERENCES public.scout_signals(id,tenant_id), FOREIGN KEY(business_id,tenant_id) REFERENCES public.scout_businesses(id,tenant_id), FOREIGN KEY(solution_id,tenant_id) REFERENCES public.scout_solution_catalog(id,tenant_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.scout_opportunities TO authenticated; GRANT ALL ON public.scout_opportunities TO service_role;
ALTER TABLE public.scout_opportunities ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.scout_opportunity_scores (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, workspace_id uuid NOT NULL, opportunity_id uuid NOT NULL, components jsonb NOT NULL, weights jsonb NOT NULL, total integer NOT NULL CHECK(total BETWEEN 0 AND 100), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,tenant_id), FOREIGN KEY(workspace_id,tenant_id) REFERENCES public.scout_workspaces(id,tenant_id), FOREIGN KEY(opportunity_id,tenant_id) REFERENCES public.scout_opportunities(id,tenant_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.scout_opportunity_scores TO authenticated; GRANT ALL ON public.scout_opportunity_scores TO service_role;
ALTER TABLE public.scout_opportunity_scores ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.scout_outreach_drafts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, workspace_id uuid NOT NULL, opportunity_id uuid NOT NULL, channel text NOT NULL DEFAULT 'Email', messages jsonb NOT NULL DEFAULT '[]', status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','approved','sent')), simulated boolean NOT NULL DEFAULT true CHECK(simulated), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,tenant_id), FOREIGN KEY(workspace_id,tenant_id) REFERENCES public.scout_workspaces(id,tenant_id), FOREIGN KEY(opportunity_id,tenant_id) REFERENCES public.scout_opportunities(id,tenant_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.scout_outreach_drafts TO authenticated; GRANT ALL ON public.scout_outreach_drafts TO service_role;
ALTER TABLE public.scout_outreach_drafts ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.scout_connector_configs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, workspace_id uuid NOT NULL, provider text NOT NULL, status text NOT NULL DEFAULT 'not_connected' CHECK(status='not_connected'), credential_reference text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,tenant_id), FOREIGN KEY(workspace_id,tenant_id) REFERENCES public.scout_workspaces(id,tenant_id));
COMMENT ON COLUMN public.scout_connector_configs.credential_reference IS 'Opaque server-side secret reference only; never credentials. No connectors enabled in MVP.';
GRANT SELECT ON public.scout_connector_configs TO authenticated; GRANT ALL ON public.scout_connector_configs TO service_role;
ALTER TABLE public.scout_connector_configs ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.scout_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, workspace_id uuid NOT NULL, mode text NOT NULL DEFAULT 'demo' CHECK(mode='demo'), signal_count integer NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'completed' CHECK(status IN('running','completed','failed')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,tenant_id), FOREIGN KEY(workspace_id,tenant_id) REFERENCES public.scout_workspaces(id,tenant_id));
GRANT SELECT,INSERT,UPDATE ON public.scout_runs TO authenticated; GRANT ALL ON public.scout_runs TO service_role;
ALTER TABLE public.scout_runs ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.scout_agent_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, workspace_id uuid NOT NULL, scout_run_id uuid, agent text NOT NULL, status text NOT NULL DEFAULT 'completed', detail jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,tenant_id), FOREIGN KEY(workspace_id,tenant_id) REFERENCES public.scout_workspaces(id,tenant_id), FOREIGN KEY(scout_run_id,tenant_id) REFERENCES public.scout_runs(id,tenant_id));
GRANT SELECT,INSERT ON public.scout_agent_runs TO authenticated; GRANT ALL ON public.scout_agent_runs TO service_role;
ALTER TABLE public.scout_agent_runs ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.scout_approvals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, workspace_id uuid NOT NULL, opportunity_id uuid NOT NULL, actor_user_id uuid NOT NULL DEFAULT auth.uid(), action text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,tenant_id), FOREIGN KEY(workspace_id,tenant_id) REFERENCES public.scout_workspaces(id,tenant_id), FOREIGN KEY(opportunity_id,tenant_id) REFERENCES public.scout_opportunities(id,tenant_id));
GRANT SELECT,INSERT ON public.scout_approvals TO authenticated; GRANT ALL ON public.scout_approvals TO service_role;
ALTER TABLE public.scout_approvals ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.scout_outreach_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, workspace_id uuid NOT NULL, opportunity_id uuid, actor_user_id uuid NOT NULL DEFAULT auth.uid(), event_key text NOT NULL, kind text NOT NULL, detail text NOT NULL, simulated boolean NOT NULL DEFAULT true CHECK(simulated), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,tenant_id), UNIQUE(workspace_id,event_key), FOREIGN KEY(workspace_id,tenant_id) REFERENCES public.scout_workspaces(id,tenant_id), FOREIGN KEY(opportunity_id,tenant_id) REFERENCES public.scout_opportunities(id,tenant_id));
GRANT SELECT,INSERT ON public.scout_outreach_events TO authenticated; GRANT ALL ON public.scout_outreach_events TO service_role;
ALTER TABLE public.scout_outreach_events ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.scout_outcome_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, workspace_id uuid NOT NULL, opportunity_id uuid NOT NULL, actor_user_id uuid NOT NULL DEFAULT auth.uid(), outcome text NOT NULL CHECK(outcome IN('reply','booked','won','lost')), simulated boolean NOT NULL DEFAULT true CHECK(simulated), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,tenant_id), FOREIGN KEY(workspace_id,tenant_id) REFERENCES public.scout_workspaces(id,tenant_id), FOREIGN KEY(opportunity_id,tenant_id) REFERENCES public.scout_opportunities(id,tenant_id));
GRANT SELECT,INSERT ON public.scout_outcome_events TO authenticated; GRANT ALL ON public.scout_outcome_events TO service_role;
ALTER TABLE public.scout_outcome_events ENABLE ROW LEVEL SECURITY;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['scout_sources','scout_businesses','scout_contacts','scout_signals','scout_solution_catalog','scout_playbooks','scout_opportunities','scout_opportunity_scores','scout_outreach_drafts','scout_connector_configs','scout_runs','scout_agent_runs','scout_approvals','scout_outreach_events','scout_outcome_events'] LOOP
EXECUTE format('CREATE POLICY %I ON public.%I FOR SELECT TO authenticated USING (EXISTS(SELECT 1 FROM public.scout_workspaces w WHERE w.id=workspace_id AND w.tenant_id=%I.tenant_id AND public.is_account_member(w.account_id)))',t||'_read',t,t);
IF t <> 'scout_connector_configs' THEN EXECUTE format('CREATE POLICY %I ON public.%I FOR ALL TO authenticated USING (EXISTS(SELECT 1 FROM public.scout_workspaces w WHERE w.id=workspace_id AND w.tenant_id=%I.tenant_id AND public.has_account_role(w.account_id,ARRAY[''owner'',''admin'',''operator'']::public.account_role[]))) WITH CHECK (EXISTS(SELECT 1 FROM public.scout_workspaces w WHERE w.id=workspace_id AND w.tenant_id=%I.tenant_id AND public.has_account_role(w.account_id,ARRAY[''owner'',''admin'',''operator'']::public.account_role[])))',t||'_write',t,t,t); END IF;
EXECUTE format('CREATE INDEX %I ON public.%I(tenant_id,created_at)',t||'_tenant_created',t);
END LOOP; END $$;
CREATE INDEX scout_opportunities_queue ON public.scout_opportunities(tenant_id,status,score DESC,created_at DESC);
CREATE INDEX scout_workspaces_tenant ON public.scout_workspaces(tenant_id);
